scenes=[dict(id=i,start=a,end=b,title=n) for i,a,b,n in segments]
captions=[dict(t=t,big=a,small=b) for t,a,b in rows]
cues=[dict(t=s['start'],name='impact',strength=.6) for s in scenes]
cues += [dict(t=c['t'],name='glass',strength=.18) for c in captions if c['t'] not in [s['start'] for s in scenes]]
cues += [dict(t=s['end']-.65,name='riser',strength=.55,duration=.65) for s in scenes[:-1]]
cfg=dict(title='偶然的秩序',duration=224,width=1920,height=1080,fps=30,bpm=120,scenes=scenes,captions=captions,cues=sorted(cues,key=lambda c:c['t']))
(ROOT/'timeline.json').write_text(json.dumps(cfg,ensure_ascii=False,indent=2),encoding='utf8')
print(len(scenes),'scenes,',len(captions),'caption beats,',cfg['duration']*cfg['fps'],'frames')
